"""Result serialization.

Secret: the wire format of the result (compact JSON with a ``completions``
array of name/complete/type/description objects, a ``definitions`` array of
definition objects, a ``signatures`` array, a ``references`` array, an
``errors`` array, or ``changed_files``/``renames`` maps, newline-terminated;
or a unified diff as plain text).
"""

import json
import sys


_DEFINITION_FIELDS = ("name", "type", "full_name", "module_path", "line", "column",
                      "description", "docstring")


def write_completions(completions, stream=None):
    """``completions``: iterable of (name, complete, type, description)."""
    payload = {"completions": [
        {"name": name, "complete": complete, "type": kind, "description": description}
        for name, complete, kind, description in completions
    ]}
    _write(payload, stream)


def write_definitions(definitions, stream=None):
    """``definitions``: iterable of dicts with the definition fields."""
    payload = {"definitions": [{field: d[field] for field in _DEFINITION_FIELDS}
                               for d in definitions]}
    _write(payload, stream)


def write_signatures(signatures, stream=None):
    """``signatures``: dicts with name, params, index, description, docstring."""
    fields = ("name", "params", "index", "description", "docstring")
    _write({"signatures": [{f: s[f] for f in fields} for s in signatures]}, stream)


def write_references(references, stream=None):
    """``references``: dicts with module_path, line, column, is_definition."""
    fields = ("module_path", "line", "column", "is_definition")
    _write({"references": [{f: r[f] for f in fields} for r in references]}, stream)


def write_search_results(definitions, stream=None):
    """``definitions``: definition dicts (their docstrings are left out)."""
    fields = [f for f in _DEFINITION_FIELDS if f != "docstring"]
    found = [{f: d[f] for f in fields} for d in definitions]
    _write({"definitions": found, "results": found}, stream)


def write_names(definitions, stream=None):
    """``definitions``: definition dicts with ``is_definition``."""
    fields = _DEFINITION_FIELDS + ("is_definition",)
    found = [{f: d[f] for f in fields} for d in definitions]
    _write({"definitions": found, "names": found}, stream)


def write_errors(errors, stream=None):
    """``errors``: dicts with line, column, until_line, until_column, message."""
    fields = ("line", "column", "until_line", "until_column", "message")
    _write({"errors": [{f: e[f] for f in fields} for e in errors]}, stream)


def write_changes(changed_files, renames, stream=None):
    """``changed_files``: path -> new content; ``renames``: old path -> new path."""
    _write({"changed_files": changed_files, "renames": renames}, stream)


def write_text(text, stream=None):
    _emit(text, stream)


def _write(payload, stream):
    _emit(json.dumps(payload, separators=(",", ":"), ensure_ascii=False) + "\n", stream)


def _emit(text, stream):
    stream = stream or sys.stdout
    if hasattr(stream, "buffer"):
        stream.flush()
        stream.buffer.write(text.encode("utf-8"))
        stream.buffer.flush()
    else:
        stream.write(text)
        stream.flush()
"""Query matching.

Secret: the algorithm deciding whether a typed query matches a candidate
name (case-insensitive prefix, or case-insensitive in-order subsequence when
fuzzy) and how much of the name remains to be inserted.
"""


def matches(name, query, fuzzy=False):
    if not query:
        return True
    name, query = name.lower(), query.lower()
    if not fuzzy:
        return name.startswith(query)
    position = 0
    for ch in query:
        position = name.find(ch, position)
        if position < 0:
            return False
        position += 1
    return True


def remaining_text(name, query):
    """Text to insert: the name minus as many characters as were typed."""
    return name[len(query):]
"""Completion wording.

Secret: the vocabulary used for a completion's ``type`` field and the
format of its human-readable ``description``.
"""

KEYWORD = "keyword"


def describe(name, kind, type_name=None):
    """Return ``(type, description)`` for a name of the given kind."""
    if kind == "module":
        return "module", "module %s" % name
    if kind == "class":
        return "class", "class %s" % name
    if kind == "function":
        return "function", "def %s(...)" % name
    if kind == "instance":
        return "instance", "instance of %s" % (type_name or "object")
    if kind == "param":
        return "param", "param %s" % name
    if kind == KEYWORD:
        return "keyword", name
    return "statement", "statement"
"""Completion ordering.

Secret: the ranking rules — public names, then private, then dunder names,
then keywords, each group alphabetical ignoring case.
"""


def _group(name, is_keyword):
    if is_keyword:
        return 3
    if name.startswith("__") and name.endswith("__"):
        return 2
    if name.startswith("_"):
        return 1
    return 0


def rank(items, name_of, is_keyword):
    """Return ``items`` sorted; ``name_of``/``is_keyword`` describe an item."""
    return sorted(items, key=lambda item: (_group(name_of(item), is_keyword(item)),
                                           name_of(item).lower(), name_of(item)))
"""Source file access.

Secret: how a file on disk is read, decoded and split into lines, and how a
(1-based line, 0-based column) cursor is validated against it.
"""

import os


class SourceError(Exception):
    """The file cannot be used as input (missing, undecodable, bad cursor)."""


class SourceFile:
    def __init__(self, path):
        if not os.path.isfile(path):
            raise SourceError("not a regular file: %s" % path)
        try:
            with open(path, "rb") as handle:
                raw = handle.read()
        except OSError as exc:
            raise SourceError("cannot read %s: %s" % (path, exc))
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise SourceError("file is not valid UTF-8: %s" % path)
        if text.startswith("\ufeff"):
            text = text[1:]
        text = text.replace("\r\n", "\n").replace("\r", "\n")
        self._path = os.path.abspath(path)
        self._lines = text.split("\n")

    @property
    def path(self):
        return self._path

    def text(self):
        return "\n".join(self._lines)

    def lines(self):
        """The file's lines without line terminators (a copy)."""
        return list(self._lines)

    def check_position(self, line, col):
        if line < 1 or line > len(self._lines):
            raise SourceError("line %d out of range" % line)
        if col < 0 or col > len(self._lines[line - 1]):
            raise SourceError("column %d out of range" % col)

    def text_before(self, line, col):
        """All text from the start of the file up to the cursor."""
        head = self._lines[: line - 1]
        head.append(self._lines[line - 1][:col])
        return "\n".join(head)
"""Runtime object introspection.

Secret: how a live Python object is classified (module, class, function or
instance) and how its attributes are enumerated and fetched safely.
"""

import inspect

MODULE = "module"
CLASS = "class"
FUNCTION = "function"
INSTANCE = "instance"


def kind_of(obj):
    if inspect.ismodule(obj):
        return MODULE
    if isinstance(obj, type):
        return CLASS
    if inspect.isroutine(obj):
        return FUNCTION
    return INSTANCE


def type_name(obj):
    """Name of the type of ``obj`` (for describing instances)."""
    return type(obj).__name__


def class_name(cls):
    return getattr(cls, "__name__", type(cls).__name__)


def attribute_names(obj):
    try:
        return [n for n in dir(obj) if isinstance(n, str)]
    except Exception:
        return []


def get_attribute(obj, name):
    """Return ``(True, value)`` or ``(False, None)`` if fetching fails."""
    try:
        return True, getattr(obj, name)
    except BaseException:  # noqa: B902 - descriptors may raise anything
        return False, None


def is_data_descriptor(obj):
    return inspect.isdatadescriptor(obj)


_SAFE_SAMPLE_MODULES = ("builtins",)


def sample_instance(cls):
    """An instance of ``cls`` built without side effects, or None."""
    if getattr(cls, "__module__", None) not in _SAFE_SAMPLE_MODULES:
        return None
    try:
        return cls()
    except BaseException:  # noqa: B902 - constructors may raise anything
        return None
"""Language vocabulary.

Secret: where the builtin namespace and the keyword list come from (here:
the running interpreter's ``builtins`` and ``keyword`` modules).
"""

import builtins
import keyword


def keywords():
    return list(keyword.kwlist)


def builtin_namespace():
    """The object whose attributes are the builtin names."""
    return builtins


def builtin_names():
    """Builtin names, excluding those that are reserved keywords."""
    reserved = set(keyword.kwlist)
    return [name for name in dir(builtins) if name not in reserved]

"""Module location.

Secret: how an imported module name is found — first as a source file or
package in the project directory, then as a type stub (``.pyi``) standing
alone, otherwise by importing a standard library module at runtime (with its
side effects contained) — where the stub of a source module is looked for,
how the module names importable from a place are enumerated, and which files
make up the project.
"""

import contextlib
import importlib
import io
import os
import pkgutil
import sys
import sysconfig

SOURCE = "source"  # a ``.py`` file, or a ``.pyi`` stub without one
RUNTIME = "runtime"
DIRECTORY = "directory"


class Located:
    """Where a module lives: a source file, a bare directory, or a live module."""

    def __init__(self, how, path=None, module=None):
        self.how = how
        self.path = path
        self.module = module


class ModuleLocator:
    def __init__(self, project_dir):
        self._project_dir = os.path.abspath(project_dir)
        self._runtime_cache = {}

    def locate(self, dotted, level=0, importer_path=None):
        """Locate ``dotted`` (relative to ``importer_path`` when ``level`` > 0)."""
        parts = [p for p in dotted.split(".") if p] if dotted else []
        if level > 0:
            base = self.relative_base(level, importer_path)
            return self._locate_in(base, parts, stubs=True) if base is not None else None
        if not parts:
            return None
        namespace = None
        for root in self.search_roots(importer_path):
            found = self._locate_in(root, parts)
            if found is not None and found.how == SOURCE:
                return found
            namespace = namespace or found
        if namespace is not None and _holds_python(namespace.path):
            return namespace
        for root in self.search_roots(importer_path) + [self.stubs_dir()]:
            found = self._locate_in(root, parts, stubs=True)
            if found is not None and found.how == SOURCE:
                return found
        module = self._import_runtime(".".join(parts))
        if module is not None:
            return Located(RUNTIME, module=module)
        return namespace

    def relative_base(self, level, importer_path):
        """Directory a relative import of ``level`` dots starts from, or None
        when it would leave the project."""
        base = os.path.dirname(os.path.abspath(importer_path or self._project_dir))
        for _ in range(level - 1):
            base = os.path.dirname(base)
        if base != self._project_dir and not base.startswith(
                self._project_dir.rstrip(os.sep) + os.sep):
            return None
        return base

    def stubs_dir(self):
        return os.path.join(self._project_dir, "stubs")

    def stub_for(self, path):
        """The ``.pyi`` stub giving type information for source file ``path``, or None."""
        path = os.path.abspath(path)
        if not path.endswith(".py"):
            return None
        adjacent = path + "i"
        if os.path.isfile(adjacent):
            return adjacent
        relative = os.path.relpath(path, self._project_dir)
        if relative.startswith(os.pardir + os.sep) or os.path.isabs(relative):
            return None
        parts = relative[:-3].split(os.sep)
        if parts[-1] == "__init__":
            parts.pop()
        if not parts:
            return None
        base = os.path.join(self.stubs_dir(), *parts)
        for candidate in (base + ".pyi", os.path.join(base, "__init__.pyi")):
            if os.path.isfile(candidate):
                return candidate
        return None

    def source_for(self, stub_path):
        """The source file that the ``.pyi`` stub at ``stub_path`` describes, or None."""
        stub_path = os.path.abspath(stub_path)
        adjacent = stub_path[:-1]
        if os.path.isfile(adjacent):
            return adjacent
        relative = os.path.relpath(stub_path, self.stubs_dir())
        if relative.startswith(os.pardir + os.sep) or os.path.isabs(relative):
            return None
        parts = relative[:-4].split(os.sep)
        if parts[-1] == "__init__":
            parts.pop()
        found = self._locate_in(self._project_dir, parts) if parts else None
        if found is None or found.how != SOURCE or self.stub_for(found.path) != stub_path:
            return None
        return found.path

    def search_roots(self, importer_path=None):
        roots = [self._project_dir]
        if importer_path:
            own = os.path.dirname(os.path.abspath(importer_path))
            if own not in roots:
                roots.append(own)
        return roots

    def top_level_names(self, importer_path=None):
        """Names of the modules ``import <name>`` can find."""
        names = set()
        for root in self.search_roots(importer_path):
            names.update(directory_module_names(root))
        names.update(stdlib_names())
        return names

    def locate_in_directory(self, directory, name):
        """Locate submodule ``name`` of the package stored in ``directory``."""
        return self._locate_in(directory, [name])

    def _locate_in(self, base, parts, stubs=False):
        """With ``stubs``, ``.pyi`` files stand in for missing ``.py`` files."""
        suffixes = (".py", ".pyi") if stubs else (".py",)
        path = base
        for index, part in enumerate(parts):
            last = index == len(parts) - 1
            package = os.path.join(path, part)
            regular = any(os.path.isfile(os.path.join(package, "__init__" + suffix))
                          for suffix in suffixes)
            module = [package + s for s in suffixes if os.path.isfile(package + s)]
            if os.path.isdir(package) and (regular or not module):
                if last:
                    return self._package(package, suffixes)
                path = package
                continue
            if last and module:
                return Located(SOURCE, path=module[0])
            return None
        return self._package(path, suffixes)

    @staticmethod
    def _package(directory, suffixes=(".py",)):
        for suffix in suffixes:
            init = os.path.join(directory, "__init__" + suffix)
            if os.path.isfile(init):
                return Located(SOURCE, path=init)
        return Located(DIRECTORY, path=directory)

    def _import_runtime(self, name):
        if name in self._runtime_cache:
            return self._runtime_cache[name]
        if not _is_stdlib(name):
            self._runtime_cache[name] = None
            return None
        module = None
        saved_path = list(sys.path)
        sys.path[:] = [p for p in sys.path
                       if p and os.path.abspath(p) not in (self._project_dir, _TOOL_DIR)]
        try:
            with _silenced_descriptors(), contextlib.redirect_stdout(io.StringIO()), \
                    contextlib.redirect_stderr(io.StringIO()):
                module = importlib.import_module(name)
        except BaseException:  # noqa: B902 - arbitrary import code may do anything
            module = None
        finally:
            sys.path[:] = saved_path
        self._runtime_cache[name] = module
        return module


@contextlib.contextmanager
def _silenced_descriptors():
    """Route OS-level stdout/stderr to the null device (for C extensions)."""
    saved = []
    try:
        sys.stdout.flush()
        sys.stderr.flush()
        devnull = os.open(os.devnull, os.O_WRONLY)
        for fd in (1, 2):
            saved.append((fd, os.dup(fd)))
            os.dup2(devnull, fd)
        os.close(devnull)
    except (OSError, ValueError, AttributeError):
        pass
    try:
        yield
    finally:
        for fd, copy in saved:
            os.dup2(copy, fd)
            os.close(copy)


_TOOL_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

# Standard library modules never imported for analysis (they act on import).
_UNSAFE = ("antigravity", "this", "__main__", "idlelib.idle", "idlelib.__main__")


def _is_stdlib(name):
    if name in _UNSAFE or name.endswith(".__main__"):
        return False
    top = name.split(".")[0]
    return top in getattr(sys, "stdlib_module_names", ()) or top in sys.builtin_module_names


_STDLIB_NAMES = None


def stdlib_names():
    """Top-level standard library modules available in this runtime."""
    global _STDLIB_NAMES
    if _STDLIB_NAMES is None:
        known = set(getattr(sys, "stdlib_module_names", ())) | set(sys.builtin_module_names)
        found = set(sys.builtin_module_names)
        directories = []
        for key in ("stdlib", "platstdlib"):
            path = sysconfig.get_paths().get(key)
            if path:
                directories += [path, os.path.join(path, "lib-dynload")]
        directories += [os.path.dirname(os.__file__)]
        directories = [d for d in dict.fromkeys(directories) if os.path.isdir(d)]
        try:
            found.update(info.name for info in pkgutil.iter_modules(directories))
        except (OSError, ImportError):
            pass
        _STDLIB_NAMES = {n for n in found & known if n not in _UNSAFE}
    return set(_STDLIB_NAMES)


def _holds_python(directory, depth=3):
    """Whether a namespace directory contains Python sources (near the top)."""
    try:
        entries = os.listdir(directory)
    except OSError:
        return False
    for entry in entries:
        path = os.path.join(directory, entry)
        if entry.endswith(".py") and os.path.isfile(path):
            return True
        if depth > 1 and entry.isidentifier() and os.path.isdir(path) \
                and _holds_python(path, depth - 1):
            return True
    return False


def directory_module_names(directory):
    """Modules and packages (regular or namespace) stored directly in ``directory``."""
    names = set()
    try:
        entries = os.listdir(directory)
    except OSError:
        return names
    for entry in entries:
        path = os.path.join(directory, entry)
        if entry.endswith(".py") and os.path.isfile(path):
            name = entry[:-3]
        elif os.path.isdir(path):
            name = entry
        else:
            continue
        if name.isidentifier() and name not in ("__init__", "__pycache__", "__main__"):
            names.add(name)
    return names


def runtime_submodule_names(module):
    """Submodules of a live package."""
    path = getattr(module, "__path__", None)
    if not path:
        return set()
    try:
        return {info.name for info in pkgutil.iter_modules(list(path))
                if info.name.isidentifier() and info.name != "__main__"}
    except (OSError, ImportError, TypeError):
        return set()


_SKIPPED_DIRECTORIES = ("__pycache__", "node_modules", "site-packages")


def project_files(root, suffix=".py"):
    """Files ending in ``suffix`` below ``root`` (hidden and cache directories
    skipped), sorted."""
    found = []
    for directory, subdirectories, files in os.walk(root):
        subdirectories[:] = sorted(d for d in subdirectories
                                   if not d.startswith(".") and d not in _SKIPPED_DIRECTORIES)
        for name in files:
            if name.endswith(suffix) and not name.startswith("."):
                found.append(os.path.join(directory, name))
    return sorted(found)

"""Static inference.

Secret: how bindings and expressions are mapped to values (modules, classes,
functions, instances), how names are resolved through scopes, flow states,
star imports and builtins, how narrowing conditions restrict values, how
the members of a value are enumerated, how a source file's ``.pyi`` stub
overrides its type information (values computed in a stub are mapped back to
the source definitions they stand for), and how unannotated parameters get
values from the call sites in their own file.

Clients see these abstractions:
  * ``Project``  - opens the main file and returns a ``Location`` for a cursor.
  * ``Where``    - an evaluation point: a scope plus the flow state there.
  * ``Value``    - has ``kind``, ``type_name`` and ``members()``; evaluation
                   always yields a list of possible values (a union).
  * ``Entity``   - a named member/visible name with ``presentation()`` giving
                   ``(kind, type_name)`` and ``values()`` giving its values.
Name resolution yields *targets*: ``scopes.Binding`` objects for names bound
in source, or ``Entity`` objects for names provided at runtime.
"""

import ast
import builtins
import io
import os
import types

from . import flow, introspect, scopes, vocabulary
from .modules import (DIRECTORY, RUNTIME, SOURCE, ModuleLocator, directory_module_names,
                      runtime_submodule_names)


# ---------------------------------------------------------------------------
# Entities

class Entity:
    name = None

    def presentation(self):
        return (STATEMENT, None)

    def values(self):
        return []


class RuntimeEntity(Entity):
    """An attribute of a live object, or of a class standing in for an instance."""

    def __init__(self, project, name, owner, from_class=None):
        self.project = project
        self.name = name
        self._owner = owner
        self._from_class = from_class

    def fetch(self):
        if self._owner is not None:
            return introspect.get_attribute(self._owner, self.name)
        ok, obj = introspect.get_attribute(self._from_class, self.name)
        if ok and introspect.is_data_descriptor(obj):
            return False, None
        return ok, obj

    def owner_name(self):
        """Qualified name of the object or class this is an attribute of."""
        owner = self._from_class if self._from_class is not None else self._owner
        if isinstance(owner, types.ModuleType):
            return owner.__name__
        if not isinstance(owner, type):
            owner = type(owner)
        return "%s.%s" % (owner.__module__, owner.__qualname__)

    def presentation(self):
        ok, obj = self.fetch()
        if not ok:
            return (STATEMENT, None)
        kind = introspect.kind_of(obj)
        if kind == INSTANCE:
            return (INSTANCE, introspect.type_name(obj))
        return (kind, None)

    def values(self):
        ok, obj = self.fetch()
        if not ok:
            return []
        owner = self._from_class
        if owner is None:
            owner = self._owner if isinstance(self._owner, type) else type(self._owner)
        return [RuntimeValue(self.project, obj, owner)]


class ValueEntity(Entity):
    """A name whose values are produced on demand (e.g. a submodule)."""

    def __init__(self, name, fetch, kind=None):
        self.name = name
        self._fetch = fetch
        self._kind = kind
        self._values = None

    def presentation(self):
        if self._kind is not None:
            return (self._kind, None)
        values = self.values()
        if not values:
            return (STATEMENT, None)
        if values[0].kind == INSTANCE:
            return (INSTANCE, values[0].type_name)
        if values[0].kind in (MODULE, CLASS, FUNCTION):
            return (values[0].kind, None)
        return (STATEMENT, None)

    def values(self):
        if self._values is None:
            found = self._fetch()
            self._values = [found] if isinstance(found, Value) else list(found or [])
        return list(self._values)


class BindingEntity(Entity):
    def __init__(self, analysis, binding):
        self._analysis = analysis
        self.binding = binding
        self.name = binding.name

    def presentation(self):
        form = self.binding.form
        if form == scopes.DEF:
            return (FUNCTION, None)
        if form == scopes.CLASS:
            return (CLASS, None)
        if form == scopes.PARAM:
            return (PARAM, None)
        if form == scopes.IMPORT:
            return (MODULE, None)
        if form in (scopes.IMPORT_FROM, scopes.ASSIGN, scopes.EXCEPT):
            values = self.values()
            value = values[0] if values else Value()
            if value.kind == INSTANCE:
                return (INSTANCE, value.type_name)
            if form == scopes.IMPORT_FROM and value.kind in (MODULE, CLASS, FUNCTION):
                return (value.kind, None)
        return (STATEMENT, None)

    def values(self):
        return self._analysis.binding_values(self.binding)


class AttributeEntity(Entity):
    """An instance attribute assigned (possibly several times) in methods."""

    def __init__(self, analysis, bindings):
        self._analysis = analysis
        self.bindings = bindings
        self.name = bindings[0].name

    def presentation(self):
        values = self.values()
        if values and values[0].kind == INSTANCE:
            return (INSTANCE, values[0].type_name)
        return (STATEMENT, None)

    def values(self):
        result = []
        for binding in self.bindings:
            result.extend(self._analysis.binding_values(binding))
        return _unique(result)


# ---------------------------------------------------------------------------
# Analysis of one file

class Analysis:
    """Inference over one source file."""

    def __init__(self, project, path, text):
        self.project = project
        self.path = path
        self.tree = scopes.ScopeTree(text, path)
        self.tree.analysis = self
        self._scope_by_node = {}
        self._index(self.tree.module)
        self._module_members = None
        self._flows = {}
        self._binding_cache = {}
        self.is_stub = path.endswith(".pyi")
        self.stub = None     # for a source file: the Analysis of its stub
        self.stub_of = None  # for a stub: the Analysis of the source file it describes
        self._stub_cache = {}
        self._calls = None

    def _index(self, scope):
        for child in scope.children:
            self._scope_by_node[id(child.node)] = child
            self._index(child)

    def scope_of(self, node):
        return self._scope_by_node.get(id(node))

    def package_dir(self):
        if os.path.basename(self.path) == "__init__.py":
            return os.path.dirname(self.path)
        return None

    def location(self, line, col, indent):
        return Location(self, self.tree.scope_at(line, col), line, col, indent)

    def none_value(self):
        return RuntimeInstance(self.project, type(None))

    # -- flow ------------------------------------------------------------
    def flow(self, scope):
        analysis = scope.tree.analysis
    def visible(self, scope, line):
        result = {name: RuntimeEntity(self.project, name, vocabulary.builtin_namespace())
                  for name in vocabulary.builtin_names()}
        for level in reversed(scope.chain()):
            for event in level.events_until_line(line):
                self._apply(result, event)
        return result

    # -- name resolution -------------------------------------------------
    def resolve(self, name, where):
        """Targets ``name`` may refer to at ``where``: list of (target, constraints)."""
        scope = where.scope
        if scope.parent is not None and name in scope.globals_declared:
            module = scope
            while module.parent is not None:
                module = module.parent
            return self.resolve(name, Where(module))
        state = where.state if where.state is not None else self.flow(scope).end
        facts = state.facts(name)
        if facts:
            result = []
            for binding, constraints in sorted(facts, key=_fact_order):
                if binding is flow.OUTER:
